const sleep=ms=>new Promise(done=>setTimeout(done,ms));let socket,logs='';browser.stderr.on('data',value=>logs=(logs+value).slice(-4000));
try{
 let port;for(let attempt=0;attempt<60;attempt++){try{port=(await readFile(join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch(_){await sleep(100);}}
 if(!port)throw new Error(logs);
 const targets=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();socket=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise((done,reject)=>{socket.addEventListener('open',done,{once:true});socket.addEventListener('error',reject,{once:true});});
 let id=0;const pending=new Map(),exceptions=[];
 socket.addEventListener('message',event=>{const r=JSON.parse(event.data);if(r.id){const p=pending.get(r.id);pending.delete(r.id);r.error?p.reject(new Error(r.error.message)):p.resolve(r.result);}else if(r.method==='Runtime.exceptionThrown')exceptions.push(r.params.exceptionDetails);});
 const call=(method,params={})=>new Promise((resolve,reject)=>{const key=++id;pending.set(key,{resolve,reject});socket.send(JSON.stringify({id:key,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
 await call('Runtime.enable');await call('Page.enable');
 for(let i=0;i<60;i++){if(await evaluate("document.readyState==='complete' && document.querySelector('#case-select').options.length===2"))break;await sleep(100);}
 const results=await evaluate(`(()=>{
  const checks=[],snapshots=[];
