  loadCase(0);let records=JSON.parse(el('all-records').textContent);
  assert(current.schema_valid===false&&records.schema_valid===false,'actual saved false flag remains false in bundle and all-records');
  assert(el('report-status-card').dataset.schema==='rejected'&&el('report-status').textContent.includes('Whole report rejected'),'actual whole-report rejection is visibly identified');
