  loadCase(1);records=JSON.parse(el('all-records').textContent);
  assert(current.schema_valid===true&&records.schema_valid===true&&el('report-status-card').dataset.schema==='accepted','actual saved passing flag remains true');
  assert(el('measurement-status').textContent.includes('marked one or more components for withholding')&&!el('report-status').textContent.includes('Whole report rejected'),'numeric withholding is identified without claiming whole-report rejection');
  assert(JSON.stringify(records.verification_audit)===JSON.stringify(current.verification_audit)&&JSON.stringify(records.schema_errors)==='[]'&&el('schema-errors').hidden,'passing empty schema-errors and complete audit are preserved');snapshots.push(snapshot());
  const first=document.querySelector('.component');assert(Boolean(first),'passing-case components remain available');first.click();
  assert(Boolean(selected)&&el('selected-json').textContent.length>0&&el('evidence').textContent.length>0,'component selection and evidence work after adding status');
  const prior=notes.length,report=JSON.stringify(current.report);el('correction-reason').value='Development-only UI smoke; excluded from benchmark';el('save-correction').click();
  assert(notes.length===prior+1&&JSON.stringify(current.report)===report,'separate correction leaves recorded report unchanged');
  const legacy=structuredClone(bundle.cases[0]);delete legacy.schema_valid;delete legacy.schema_errors;bundle.cases.push(legacy);loadCase(2);records=JSON.parse(el('all-records').textContent);
  assert(el('report-status-card').dataset.schema==='unknown'&&el('report-status').textContent.includes('unavailable'),'legacy bundle missing fields shows unknown even with an empty report and schema-invalid audit');
  assert(records.schema_valid===null&&records.schema_errors===null&&el('schema-errors').hidden,'legacy all-records preserves unavailable values as null rather than false or empty errors');snapshots.push(snapshot());
  const bypass=structuredClone(bundle.cases[1]);bypass.method='G1';bundle.cases.push(bypass);loadCase(3);
  assert(el('measurement-status').textContent.includes('without applying the measurement filter'),'G1 audit entries do not imply measurement filtering was applied');
  bypass.method='no_verifier';loadCase(3);assert(el('measurement-status').textContent.includes('without applying the measurement filter'),'no_verifier audit entries do not imply measurement filtering was applied');
  const nullFields=structuredClone(bundle.cases[0]);nullFields.schema_valid=null;nullFields.schema_errors=null;bundle.cases.push(nullFields);loadCase(4);
  assert(el('report-status-card').dataset.schema==='unknown'&&JSON.parse(el('all-records').textContent).schema_valid===null,'explicit null remains unknown');
  const untyped=structuredClone(bundle.cases[0]);untyped.schema_valid='false';bundle.cases.push(untyped);loadCase(5);
  assert(el('report-status-card').dataset.schema==='unknown','non-boolean flag is not silently coerced');
  const referenceBox=()=>document.querySelector('[data-layer="reference"] input');
  loadCase(0);
  assert(!sources.reference.enabled&&!referenceBox().checked&&sources.reference.label==='No AI reference supplied','missing reference is off by default and labelled as absent');
  const example=structuredClone(bundle.cases[1].report.components[0]);
  const fixture=reference=>{const c=structuredClone(bundle.cases[1]);c.reference=reference;bundle.cases.push(c);return bundle.cases.length-1;};
  const legacyReferenceIndex=fixture({events:[example]});loadCase(legacyReferenceIndex);
  assert(!sources.reference.enabled&&!referenceBox().checked&&sources.reference.label==='Legacy AI: unqualified'&&!visibleComponents().some(c=>c.source==='reference'),'absent eligibility keeps a legacy reference hidden by default');
  referenceBox().checked=true;referenceBox().dispatchEvent(new Event('change',{bubbles:true}));
  assert(sources.reference.enabled&&visibleComponents().some(c=>c.source==='reference'),'explicit opt-in displays the unqualified current-case reference');
  loadCase(1);loadCase(legacyReferenceIndex);
  assert(!sources.reference.enabled&&!referenceBox().checked,'unqualified opt-in is reset after switching cases');
  const emptyReferenceIndex=fixture({eligible_types:[],events:[example]});loadCase(emptyReferenceIndex);
  assert(!sources.reference.enabled&&!referenceBox().checked&&sources.reference.label==='AI reference: no eligible types'&&!visibleComponents().some(c=>c.source==='reference'),'empty eligible types remain off and do not imply eligible labels exist');
  const eligibleReferenceIndex=fixture({eligible_types:[example.type],events:[example]});loadCase(eligibleReferenceIndex);
  assert(sources.reference.enabled&&referenceBox().checked&&sources.reference.label==='Eligible AI reference'&&visibleComponents().some(c=>c.source==='reference'),'explicit nonempty eligible types enable the qualified layer and synchronize checkbox');
  referenceBox().checked=false;referenceBox().dispatchEvent(new Event('change',{bubbles:true}));
  assert(!sources.reference.enabled&&!visibleComponents().some(c=>c.source==='reference'),'user can turn off an eligible current-case layer');
  loadCase(eligibleReferenceIndex);
  assert(sources.reference.enabled&&referenceBox().checked,'each case load restores its recorded nonempty eligibility default');
  loadCase(emptyReferenceIndex);
  assert(!sources.reference.enabled&&!referenceBox().checked,'switching from eligible to empty eligibility clears enabled state and checkbox');
  loadCase(eligibleReferenceIndex);loadCase(legacyReferenceIndex);
  assert(!sources.reference.enabled&&!referenceBox().checked,'switching from eligible to absent eligibility clears enabled state and checkbox');
  loadCase(eligibleReferenceIndex);loadCase(0);
  assert(!sources.reference.enabled&&!referenceBox().checked,'switching from eligible to missing reference clears enabled state and checkbox');
  const wrappedReferenceIndex=fixture({annotation:{eligible_types:[example.type],events:[example]}});loadCase(wrappedReferenceIndex);
  assert(sources.reference.enabled&&referenceBox().checked,'nested annotation eligibility uses the same case default');
  const nullEligibilityIndex=fixture({eligible_types:null,events:[example]});loadCase(nullEligibilityIndex);
