 console.log(JSON.stringify({status:'passed',checks:results.checks.length,scenes:results.snapshots.map(x=>x.scene_id),runtime_exceptions:exceptions.length}));
}finally{socket?.close();browser.kill('SIGTERM');await sleep(300);await rm(profile,{recursive:true,force:true});}
